<script setup lang="ts" generic="T extends Record<string, unknown>">import {computed,ref} from 'vue';type Column={key:string;label:string;sortable?:boolean};const p=withDefaults(defineProps<{rows:T[];columns:Column[];pageSize?:number;searchable?:boolean;selectable?:boolean}>(),{pageSize:10,searchable:true});const sort=ref('');const descending=ref(false);const search=ref('');const page=ref(1);const selected=ref<string[]>([]);const filtered=computed(()=>p.rows.filter(r=>!search.value||Object.values(r).some(x=>String(x??'').toLowerCase().includes(search.value.toLowerCase()))));const ordered=computed(()=>{const arr=[...filtered.value];if(sort.value)arr.sort((a,b)=>String(a[sort.value]??'').localeCompare(String(b[sort.value]??''),undefined,{numeric:true})*(descending.value?-1:1));return arr});const pages=computed(()=>Math.max(1,Math.ceil(ordered.value.length/p.pageSize)));const visible=computed(()=>ordered.value.slice((Math.min(page.value,pages.value)-1)*p.pageSize,Math.min(page.value,pages.value)*p.pageSize));function toggleSort(k:string){if(sort.value===k)descending.value=!descending.value;else{sort.value=k;descending.value=false}}function toggleRow(k:string){selected.value=selected.value.includes(k)?selected.value.filter(s=>s!==k):[...selected.value,k]}</script><template><div class="vx-data"><input v-if="searchable" v-model="search" class="vx-control" type="search" placeholder="Search table" aria-label="Search table" @input="page=1"/><div class="vx-data__scroll"><table><thead><tr><th v-if="selectable">Select</th><th v-for="c in columns" :key="c.key"><button v-if="c.sortable" @click="toggleSort(c.key)">{{c.label}} {{sort===c.key?(descending?'↓':'↑'):'↕'}}</button><span v-else>{{c.label}}</span></th></tr></thead><tbody><tr v-for="(r,i) in visible" :key="i"><td v-if="selectable"><input type="checkbox" :aria-label="'Select row '+(i+1)" :checked="selected.includes(String(r.id??i))" @change="toggleRow(String(r.id??i))"/></td><td v-for="c in columns" :key="c.key" :data-label="c.label">{{r[c.key]}}</td></tr><tr v-if="!visible.length"><td :colspan="columns.length+(selectable?1:0)">No matching records</td></tr></tbody></table></div><nav aria-label="Table pagination" class="vx-pagination"><span>{{filtered.length}} records</span><button :disabled="page===1" @click="page--">Previous</button><span>{{Math.min(page,pages)}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">Next</button></nav></div></template>